import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import styled from 'styled-components';

const FuelPage = () => {
    const { id: lorryId } = useParams(); // Fetch lorryId from the URL
    const [fuelData, setFuelData] = useState([]);
    const [newFuel, setNewFuel] = useState({
        fill_date: '',
        bunk_name: '',
        total_amount: '',
        amount_paid: ''
    });

    useEffect(() => {
        fetchFuelData();
    }, [lorryId]);

    // Fetch fuel data for the lorry
    const fetchFuelData = async () => {
        try {
            const response = await axios.get(`http://localhost:5000/api/fuel/${lorryId}`);
            setFuelData(response.data);
        } catch (error) {
            console.error('Error fetching fuel data:', error);
        }
    };

    // Handle form input changes
    const handleInputChange = (e) => {
        setNewFuel({ ...newFuel, [e.target.name]: e.target.value });
    };

    // Add a new fuel record
    const handleAddFuel = async (e) => {
        e.preventDefault();
        try {
            await axios.post('http://localhost:5000/api/fuel/add', {
                lorry_id: lorryId,
                ...newFuel
            });
            alert('Fuel record added successfully!');
            fetchFuelData(); // Refresh fuel data after adding a new record
        } catch (error) {
            console.error('Error adding fuel record:', error);
        }
    };

    return (
        <Container>
            <h1>Fuel Records for Lorry #{lorryId}</h1>
            <Form onSubmit={handleAddFuel}>
                <Input type="date" name="fill_date" value={newFuel.fill_date} onChange={handleInputChange} required />
                <Input type="text" name="bunk_name" placeholder="Bunk Name" value={newFuel.bunk_name} onChange={handleInputChange} required />
                <Input type="number" name="total_amount" placeholder="Total Amount" value={newFuel.total_amount} onChange={handleInputChange} required />
                <Input type="number" name="amount_paid" placeholder="Amount Paid" value={newFuel.amount_paid} onChange={handleInputChange} required />
                <Button type="submit">Add Fuel Record</Button>
            </Form>

            <Table>
                <thead>
                    <tr>
                        <th>Date</th>
                        <th>Bunk Name</th>
                        <th>Total Amount</th>
                        <th>Amount Paid</th>
                        <th>Remaining Amount</th>
                    </tr>
                </thead>
                <tbody>
                    {fuelData.map((fuel, index) => (
                        <tr key={index}>
                            <td>{fuel.fill_date}</td>
                            <td>{fuel.bunk_name}</td>
                            <td>{fuel.total_amount}</td>
                            <td>{fuel.amount_paid}</td>
                            <td>{fuel.remaining_amount}</td>
                        </tr>
                    ))}
                </tbody>
            </Table>
        </Container>
    );
};

// Styled Components
const Container = styled.div` padding: 20px; `;
const Form = styled.form` display: flex; flex-direction: column; gap: 10px; `;
const Input = styled.input` padding: 10px; border: 1px solid #ccc; `;
const Button = styled.button` padding: 10px; background: green; color: white; `;
const Table = styled.table` margin-top: 20px; width: 100%; border-collapse: collapse; `;

export default FuelPage;
